DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261120072806_AddMuseumPresence') THEN
    CREATE TABLE museum_presence (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "UserId" uuid NOT NULL,
        "MuseumId" integer NOT NULL,
        "VisitId" integer,
        "MapId" integer NOT NULL,
        "MapRevision" integer NOT NULL,
        "MarkerId" uuid NOT NULL,
        "RequestId" uuid NOT NULL,
        "ObservedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_museum_presence" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_museum_presence_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_museum_presence_indoor_maps_MapId" FOREIGN KEY ("MapId") REFERENCES indoor_maps ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_museum_presence_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_museum_presence_visits_VisitId" FOREIGN KEY ("VisitId") REFERENCES visits ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

